[metadata] {"type": "create", "filePath": "/workspace/repo/packages/codemod/src/cli.parseFlags.ts", "content": "export type ParsedFlags = {
  dry: boolean
  list: boolean
  path: string
  print: boolean
  transform: string | undefined
}

/**
 * Parses a CLI argument array into a structured flags object. The first
 * positional (non-flag) argument becomes the `path`. Recognizes `--dry`,
 * `--dry-run` (alias for `--dry`), `--list`, `--print`, and `--transform <value>`.
 */
export const parseFlags = (argv: string[]): ParsedFlags => {
  const flags: ParsedFlags = {
    dry: false,
    list: false,
    path: process.cwd(),
    print: false,
    transform: undefined,
  }

  let hasPath = false

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]

    if (arg === undefined) {
      continue
    }

    switch (arg) {
      case '--dry':
      case '--dry-run':
        flags.dry = true
        break
      case '--list':
        flags.list = true
        break
      case '--print':
        flags.print = true
        break
      case '--transform':
        flags.transform = argv[i + 1]
        i++
        break
      default:
        if (!hasPath && !arg.startsWith('-')) {
          flags.path = arg
          hasPath = true
        }
        break
    }
  }

  return flags
}
