[metadata] {"type": "create", "filePath": "/workspace/repo/packages/codemod/src/utils/test-helpers.ts", "content": "import { Project } from 'ts-morph'

import type { Transform } from '../types.js'

/**
 * Test helper that builds an in-memory ts-morph `Project` containing `source`
 * as a single TypeScript file, applies `transform`, and returns the resulting
 * file's source text.
 */
export const runTransform = async ({
  filename = 'input.ts',
  source,
  transform,
}: {
  filename?: string
  source: string
  transform: Transform
}): Promise<string> => {
  const project = new Project({ useInMemoryFileSystem: true })

  project.createSourceFile(filename, source)

  await transform.apply({ project })

  return project.getSourceFileOrThrow(filename).getFullText()
}
